/**
 * @name XXE vulnerability in Excel file loading
 * @description XML parsing from user-provided Excel files without proper defenses against XXE
 * @kind path-problem
 * @problem.severity error
 * @id py/openpyxl-xxe-file-load
 * @tags security
 *        external/cwe/cwe-611
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module XXEConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // File path parameters to load_workbook or similar functions
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("openpyxl").getMember("load_workbook").getACall() and
      source = call.getArg(0)
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // XML parsing operations from xml.etree or lxml
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("xml").getMember("etree").getMember(["ElementTree", "parse", "fromstring", "XML"]).getACall() or
        call = API::moduleImport("lxml").getMember("etree").getMember(["parse", "fromstring", "XML", "XMLParser"]).getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module XXEFlow = TaintTracking::Global<XXEConfig>;
import XXEFlow::PathGraph

from XXEFlow::PathNode source, XXEFlow::PathNode sink
where XXEFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential XXE vulnerability: user file flows to XML parser at $@.", source.getNode(), "file input"

/**
 * @name Path traversal in file operations
 * @description File operations using unsanitized user input may allow path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameters to public functions that might receive file paths
    exists(Function f, Parameter p |
      source.(DataFlow::ParameterNode).getParameter() = p and
      p = f.getAnArg() and
      (
        p.getName().matches("%path%") or
        p.getName().matches("%file%") or
        p.getName().matches("%name%") or
        p.getName().matches("%archive%")
      )
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fsa |
      sink = fsa.getAPathArgument()
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from $@.", source.getNode(), "user-controlled path"

/**
 * @name Command injection
 * @description Executing system commands with user-controlled input can lead to arbitrary command execution
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SystemCommandExecution cmd |
      sink = cmd.getCommand()
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

